// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("an even split", () -> eq(plain(split(new BigDecimal("9.00"), 3)), List.of("3.00", "3.00", "3.00")));
    test("the first people pay the extra cents", () ->
        eq(plain(split(new BigDecimal("10.00"), 3)), List.of("3.34", "3.33", "3.33")));
    test("the parts always add up to the total", () -> {
        var parts = split(new BigDecimal("100.01"), 7);
        eq(parts.stream().reduce(BigDecimal.ZERO, BigDecimal::add), new BigDecimal("100.01"));
        eq(parts.size(), 7);
    });
    test("fewer cents than people", () -> eq(plain(split(new BigDecimal("0.05"), 2)), List.of("0.03", "0.02")));
    test("one person pays it all", () -> eq(plain(split(new BigDecimal("12.5"), 1)), List.of("12.50")));
    test("a zero bill splits into zeros", () -> eq(plain(split(BigDecimal.ZERO, 2)), List.of("0.00", "0.00")));
    test("refuses nonsense", () -> {
        raises(IllegalArgumentException.class, () -> split(new BigDecimal("10.00"), 0));
        raises(IllegalArgumentException.class, () -> split(new BigDecimal("-1.00"), 2));
        raises(IllegalArgumentException.class, () -> split(new BigDecimal("10.005"), 2));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("normalises to two decimals", () -> eq(Money.of("12.5", "EUR").amount().toPlainString(), "12.50"));
    test("equal amounts are equal records", () -> {
        ok(Money.of("12.5", "EUR").equals(Money.of("12.50", "EUR")), "12.5 EUR should equal 12.50 EUR");
        eq(Money.of("12.5", "EUR").hashCode(), Money.of("12.50", "EUR").hashCode());
    });
    test("refuses a bad currency", () -> {
        raises(IllegalArgumentException.class, () -> Money.of("1", "eur"));
        raises(IllegalArgumentException.class, () -> Money.of("1", "EURO"));
    });
    test("refuses fractions of a cent", () -> raises(IllegalArgumentException.class, () -> Money.of("1.005", "EUR")));
    test("adds and subtracts", () -> {
        eq(Money.of("10", "EUR").plus(Money.of("2.5", "EUR")).toString(), "12.50 EUR");
        eq(Money.of("10", "EUR").minus(Money.of("12.25", "EUR")).toString(), "-2.25 EUR");
    });
    test("refuses to mix currencies", () -> {
        raises(IllegalArgumentException.class, () -> Money.of("1", "EUR").plus(Money.of("1", "USD")));
        raises(IllegalArgumentException.class, () -> Money.of("1", "EUR").minus(Money.of("1", "USD")));
    });
    test("multiplies by a quantity", () -> eq(Money.of("2.25", "EUR").times(3).toString(), "6.75 EUR"));
    test("prints with two decimals", () -> eq(Money.of("7", "USD").toString(), "7.00 USD"));
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("accepts a normal amount", () -> {
        eq(validateAmount("12.50"), List.of());
        eq(validateAmount(" 7 "), List.of());
    });
    test("requires something", () -> {
        eq(validateAmount(""), List.of("required"));
        eq(validateAmount(null), List.of("required"));
    });
    test("refuses text that is not a plain number", () -> {
        eq(validateAmount("abc"), List.of("not a number"));
        eq(validateAmount("1e3"), List.of("not a number"));
        eq(validateAmount("12,50"), List.of("not a number"));
    });
    test("refuses zero and negatives", () -> {
        eq(validateAmount("0"), List.of("must be positive"));
        eq(validateAmount("-5"), List.of("must be positive"));
    });
    test("allows trailing zeros but not extra decimals", () -> {
        eq(validateAmount("1.500"), List.of());
        eq(validateAmount("0.001"), List.of("at most 2 decimals"));
    });
    test("lists every problem in order", () ->
        eq(validateAmount("-0.001"), List.of("must be positive", "at most 2 decimals")));
    test("caps the amount", () -> {
        eq(validateAmount("10000.00"), List.of());
        eq(validateAmount("10000.01"), List.of("at most 10000.00"));
    });
    System.exit(report());
}
// ─── end tests ───────────────────────────────────────────────────────

// ─── tests ───────────────────────────────────────────────────────────
public static void main(String[] args) {
    test("compounds on the rounded balance", () ->
        eq(plain(schedule(d("1000.00"), d("6"), 3)), List.of("1005.00", "1010.02", "1015.07")));
    test("a rate that never divides evenly", () ->
        eq(balanceAfter(d("1000.00"), d("5"), 12).toPlainString(), "1051.16"));
    test("a fractional rate over six months", () -> eq(
        plain(schedule(d("2500.00"), d("3.5"), 6)),
        List.of("2507.29", "2514.60", "2521.93", "2529.29", "2536.67", "2544.07")));
    test("zero months leaves the principal", () -> {
        eq(balanceAfter(d("1000"), d("6"), 0).toPlainString(), "1000.00");
        eq(schedule(d("1000"), d("6"), 0), List.of());
    });
    test("a zero rate changes nothing", () -> eq(balanceAfter(d("1000.00"), d("0"), 24).toPlainString(), "1000.00"));
    test("refuses negative months", () ->
        raises(IllegalArgumentException.class, () -> schedule(d("1000.00"), d("6"), -1)));
    System.exit(report());
}
